var url = "http://192.168.137.3/inventory/network-device/count";

function setup() {
	var http = new HTTPClient();

	// when receiving data
	http.onDone = function(status, data) {
		Serial.println("status: " + status);
		Serial.println("data: " + data);
	};

	http.open(url);
}

